const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const samples={Photographer:{name:'Golden Hour Photography',contact:'Alex Morgan',email:'hello@goldenhour.example',phone:'(512) 555-0142',address:'1200 East 6th Street, Austin, TX 78702',area:'Austin + Texas Hill Country',price:'$4,200',services:'Wedding photography, engagement sessions, second photographer',bio:'Heartfelt imagery for the wildly in love. Golden Hour captures candid moments and warm, true-to-life portraits for celebrations across Austin and the Texas Hill Country.'},DJ:{name:'Good Company DJs',contact:'Sam Taylor',email:'sam@goodcompany.example',phone:'(512) 555-0188',address:'2400 South Lamar Boulevard, Austin, TX 78704',area:'Austin + Central Texas',price:'$2,400',services:'Wedding DJ, ceremony sound, MC services, dance floor lighting',bio:'Great music. Full dance floors. Good Company creates a soundtrack that feels like you, from the first walk down the aisle to the last song of the night.'},Venue:{name:'Juniper Grove',contact:'Casey Reed',email:'events@junipergrove.example',phone:'(512) 555-0166',address:'850 Creek Road, Dripping Springs, TX 78620',area:'Dripping Springs, Texas',price:'$8,500',services:'Indoor and outdoor ceremonies, reception hall, getting-ready suites',bio:'A sunlit Hill Country gathering place with ancient oaks, open skies, and room for up to 180 of your favorite people.'},Caterer:{name:'Smoke & Honey Catering',contact:'Jordan Brooks',email:'jordan@smokeandhoney.example',phone:'(512) 555-0129',address:'1900 Manor Road, Austin, TX 78722',area:'Austin + 60-mile service radius',price:'$85 per guest',services:'BBQ catering, buffet service, vegetarian menus, late-night snacks',bio:'Slow-smoked favorites and generous Southern hospitality, served with a fresh seasonal twist. Smoke & Honey brings people together over real good food.'}};
let state={page:'onboard',mode:'after',step:1,type:'Photographer',tab:'website',url:'',transcript:'',file:'',resolved:false,data:{},manual:{},approved:false};let saved=[];try{saved=JSON.parse(localStorage.getItem('bubs-vendors')||'[]')}catch{}const labels={name:'Business name',contact:'Primary contact',email:'Email address',phone:'Phone number',address:'Business address',area:'Location / service area',price:'Starting price',services:'Services offered',bio:'Vendor bio'};
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function heading(title,sub,action=''){return `<div class="heading"><div><span class="eyebrow">REAL GOOD PARTNERSHIPS START HERE</span><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function steps(){return `<div class="steps">${['Add your sources','Review the details','Meet your vendor'].map((x,i)=>`<div class="step ${state.step>=i+1?'current':''}"><i>${state.step>i+1?'✓':i+1}</i>${x}</div>`).join('')}</div>`}
function intro(){return `<div class="intro"><div><span class="tag">${state.mode==='after'?'✧ AUTOMATED ONBOARDING':'◷ THE MANUAL PROCESS'}</span><h2 style="margin-top:14px">${state.mode==='after'?'Less busywork. More “you’re booked.”':'A good conversation. A lot of copying.'}</h2><p>${state.mode==='after'?'Turn scattered vendor information into a profile ready for your review.':'Interview the vendor, find the details, and enter every field by hand.'}</p></div><div class="big-stat">${state.mode==='after'?'~5 min':'~45 min'}<small>ILLUSTRATIVE TIME / VENDOR</small></div></div>`}
function field(k,value,review=false){return `<div class="field ${['address','services','bio'].includes(k)?'full':''}"><label for="f-${k}">${labels[k]} ${review&&k==='price'&&!state.resolved?'<span style="color:#b4893b">· Needs review</span>':''}</label>${['bio','services'].includes(k)?`<textarea id="f-${k}" data-key="${k}" ${review?'':'placeholder="Enter '+labels[k].toLowerCase()+'"'}>${esc(value)}</textarea>`:`<input id="f-${k}" data-key="${k}" value="${esc(value)}" placeholder="${labels[k]}">`}${review?`<div class="evidence"><span>${k==='price'&&!state.resolved?'⚑ Conflicting sources':'✓ '+(k==='bio'?'Drafted from sources':'Source found')}</span><button onclick="showSource('${k}')">${k==='price'?'Call + website':'View source'} ↗</button></div>`:''}</div>`}
function importScreen(){return `${steps()}<div class="import-layout"><section class="card"><div class="card-head"><div><h2>Start with what you know</h2><p>Choose a vendor type, then add a source. We’ll take it from there.</p></div><span class="count">01 / 03</span></div><label for="type">Vendor category</label><select id="type">${Object.keys(samples).map(x=>`<option ${x===state.type?'selected':''}>${x}</option>`).join('')}</select><div class="source-tabs">${[['website','↗ Website / portfolio'],['social','◎ Social profile'],['transcript','≡ Call transcript']].map(([key,label])=>`<button class="${state.tab===key?'selected':''}" data-tab="${key}">${label}</button>`).join('')}</div>${state.tab==='transcript'?`<label for="transcript">Paste a call transcript</label><textarea id="transcript" placeholder="Rep: Tell me about your business…">${esc(state.transcript)}</textarea><div class="drop"><div class="symbol">↥</div><b>${esc(state.file||'Or drop a transcript here')}</b><p>TXT or VTT · up to 2 MB</p><input type="file" id="upload" accept=".txt,.vtt" hidden><button class="secondary" id="browse">Browse files</button><small>Files stay in your browser in this demo.</small></div>`:`<label for="url">${state.tab==='social'?'Social profile':'Vendor website or portfolio'} URL</label><input id="url" type="url" value="${esc(state.url)}" placeholder="https://your-vendor.example"><div class="drop"><div class="symbol">✧</div><b>See the magic with a sample vendor</b><p>Try ${esc(samples[state.type].name)} — no prep needed.</p><button class="secondary" id="sample">Use sample ${state.type.toLowerCase()} →</button><small>Fictional business · Ready-to-run demo</small></div>`}<div class="notice">ⓘ <span>This is a simulated demo. Links and transcripts demonstrate the input flow; extracted results use the selected fictional vendor sample.</span></div><div class="footer"><small>Step 1 of 3 · Sources → structured details</small><button class="primary" id="extract">Generate vendor profile &nbsp; →</button></div></section></div>`}
function manualScreen(){return `<div class="grid"><section class="card"><div class="card-head"><div><h2>The interview worksheet</h2><p>Ask, listen, take notes, then enter each detail below.</p></div><span class="tag" style="background:#f7e9de;color:#a37654">Manual entry</span></div><label for="type">Vendor category</label><select id="type" style="margin-bottom:20px">${Object.keys(samples).map(x=>`<option ${state.type===x?'selected':''}>${x}</option>`).join('')}</select><div class="fields">${Object.keys(labels).map(k=>field(k,state.manual[k]||'')).join('')}</div><div class="footer"><small>${Object.values(state.manual).filter(Boolean).length} of 9 fields entered by hand</small><button class="primary" id="manual-save">Save worksheet</button></div></section><div class="right"><section class="card side-card"><span class="tag manual-note">THE BEFORE</span><h3 style="margin-top:20px">One vendor. Many little tasks.</h3><p>1. Schedule an introductory call<br>2. Interview the vendor<br>3. Capture notes during the call<br>4. Re-enter details into the profile<br>5. Follow up on missing answers</p><div class="notice manual-note">Illustrative baseline: 30-minute call + 15 minutes of data entry.</div><button class="primary" id="switch-after" style="margin-top:20px;width:100%">Try the automated process →</button></section><section class="card side-card quote"><span class="eyebrow">SAMPLE INTERVIEW NOTES</span><p>${esc(samples[state.type].contact)} from ${esc(samples[state.type].name)} serves ${esc(samples[state.type].area)}. Packages start at ${esc(samples[state.type].price)}. Contact: ${esc(samples[state.type].email)}.</p><small>Copy details into the worksheet to experience the manual flow.</small></section></div></div>`}
function reviewScreen(){return `${steps()}<div class="grid"><section class="card"><div class="card-head"><div><h2>A real good first draft</h2><p>9 fields populated. Review the sources and make it yours.</p></div><span class="tag">✧ Generated</span></div>${!state.resolved?`<div class="warning"><b>⚑ A little clarity on pricing</b><p>The website lists ${state.type==='Caterer'?'$75 per guest':state.type==='Venue'?'$7,500':state.type==='DJ'?'$2,000':'$3,800'}. The more recent call says ${esc(samples[state.type].price)}. Confirm which starting price to use.</p><button class="secondary" id="resolve">Use recent call: ${esc(samples[state.type].price)}</button> <button class="text-btn" onclick="showSource('price')">Compare sources</button></div>`:`<div class="notice" style="margin-bottom:22px">✓ Pricing conflict resolved. Your chosen price is ready for approval.</div>`}<div class="fields">${Object.keys(labels).map(k=>field(k,state.data[k],true)).join('')}</div><div class="notice">✧ <span>Review all generated details before approval. The vendor bio is a draft; source confidence does not guarantee accuracy.</span></div><div class="footer"><button class="text-btn" id="back">← Back to sources</button><button class="primary" id="approve" ${state.resolved?'':'disabled'}>Approve vendor profile &nbsp; →</button></div></section><div class="right"><section class="card side-card"><span class="eyebrow">EXTRACTION SUMMARY</span><h3 style="margin-top:13px">A head start, with receipts.</h3><ul class="checklist"><li>Business & contact details</li><li>Address & service area</li><li>Services & starting price</li><li>A first draft of the bio</li></ul><hr style="border:0;border-top:1px solid var(--line)"><p><b>Sources in this sample</b><br>Vendor website · 6 fields<br>Introductory call · 3 fields</p><p>Sample extraction includes a pricing conflict to demonstrate rep review.</p></section><section class="card side-card quote"><h3>Human-approved.<br>Bub’s-ready.</h3><p>Automation does the first pass. You make the final call.</p></section></div></div>`}
function profile(){let d=state.data;return `${steps()}<div class="grid"><section class="card"><div class="profile-hero"><span>${state.type==='Photographer'?'love, in a golden light.':state.type==='DJ'?'one more song.':state.type==='Venue'?'a place for your forever.':'made with a little soul.'}</span></div><div class="profile-title"><div><span class="eyebrow">${esc(state.type)} · ${esc(d.area)}</span><h2 style="margin-top:9px">${esc(d.name)}</h2></div><span class="pill">✓ Approved</span></div><p>${esc(d.bio)}</p><div class="fields" style="margin-top:25px">${['price','services','contact','email','phone','address'].map(k=>`<div class="field ${k==='services'?'full':''}"><label>${labels[k]}</label><div style="font-size:12px;line-height:1.8">${esc(d[k])}</div></div>`).join('')}</div><div class="footer"><small>Approved by Jamie Rivera · Stored in this browser</small><button class="secondary" id="export">Export profile ↓</button></div></section><div class="right"><section class="card side-card"><span class="tag">✓ READY TO GO</span><h2 style="margin-top:18px">Welcome to the family.</h2><p>One more vendor onboarded. A whole lot less typing.</p><button class="primary" id="another" style="width:100%;margin-top:10px">Onboard another vendor →</button><button class="text-btn" data-page="impact" style="margin-top:15px">See the before & after</button></section><section class="card side-card quote"><h3>9 fields. One review.</h3><p>Source-backed drafts help reps spend time on relationships.</p><small>All vendor information in this demo is fictional.</small></section></div></div>`}
function impact(){return heading('A better way to say “welcome.”','From interview-heavy admin to a source-first, rep-approved workflow.')+`<div class="metrics"><div class="metric"><small>MANUAL PROCESS</small><strong>45 min</strong><small>Illustrative time per vendor</small></div><div class="metric"><small>AUTOMATED PROCESS</small><strong>5 min</strong><small>Illustrative time per vendor</small></div><div class="metric"><small>TIME GIVEN BACK</small><strong>89%</strong><small>Illustrative reduction · 40 min saved</small></div></div><div class="grid"><section class="card"><h2>Less admin between hello and onboarded.</h2><p>Manual interview + re-entry <b style="float:right">45 minutes</b></p><div class="bar"></div><p>Source import + rep review <b style="float:right">5 minutes</b></p><div class="bar fast"></div><table class="table"><thead><tr><th>WORKFLOW</th><th>BEFORE</th><th>AFTER</th></tr></thead><tbody>${[['Gather information','Schedule & conduct interview','Upload transcript or add link'],['Create profile','Type every field','Review prefilled details'],['Check accuracy','Cross-check scattered notes','Inspect field-level sources'],['Handle uncertainty','Follow up from scratch','Resolve flagged conflicts'],['Finish onboarding','Save manual worksheet','Approve structured profile']].map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table><div class="notice">ⓘ These are illustrative scenario assumptions, not measured performance. Actual results depend on source quality and review needs.</div></section><section class="card side-card"><span class="eyebrow">TRY IT YOURSELF</span><h2 style="margin-top:15px">Same vendor.<br>Different workday.</h2><p>Walk through both processes to see where the work changes.</p><button class="primary" onclick="start('after')">Try automated onboarding →</button><button class="text-btn" onclick="start('before')" style="display:block;margin-top:18px">Explore the manual process</button></section></div>`}
function directory(){return heading('Real good company.','Your approved sample vendors, all in one place.',`<button class="primary" onclick="start('after')">+ Add vendor</button>`)+`<section class="card"><div class="card-head"><h2>Vendor directory</h2><span class="count">${saved.length} approved</span></div>${saved.length?`<table class="table"><thead><tr><th>BUSINESS</th><th>CATEGORY</th><th>LOCATION</th><th>STATUS</th><th></th></tr></thead><tbody>${saved.map((v,i)=>`<tr><td><b>${esc(v.data.name)}</b><br><small>${esc(v.data.email)}</small></td><td>${esc(v.type)}</td><td>${esc(v.data.area)}</td><td><span class="pill">Approved</span></td><td><button class="text-btn" data-view="${i}">View →</button></td></tr>`).join('')}</tbody></table>`:`<div class="empty"><h2>Your next great partnership starts here.</h2><p>Approve your first vendor to see their profile in the directory.</p><button class="primary" onclick="start('after')">Onboard a sample vendor →</button></div>`}</section>`}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));$('#crumb').textContent=({onboard:'Vendor onboarding',overview:'Overview',vendors:'Vendor directory',impact:'Process comparison',transcript:'Transcript to profile',evals:'Profile evals',voice:'Voice assistant'})[state.page];if(state.page==='impact')$('#app').innerHTML=impact();else if(state.page==='vendors')$('#app').innerHTML=directory();else if(state.page==='transcript')document.getElementById('app').innerHTML=transcriptScreen();else if(state.page==='evals')document.getElementById('app').innerHTML=evalsScreen();else if(state.page==='voice')document.getElementById('app').innerHTML=voiceScreen();else if(state.page==='overview')$('#app').innerHTML=heading('Good things are coming together.','A home for your next real good vendor partnership.',`<button class="primary" onclick="start('after')">+ Onboard vendor</button>`)+`<div class="metrics"><div class="metric"><small>APPROVED IN THIS DEMO</small><strong>${saved.length}</strong><small>Profiles saved in your browser</small></div><div class="metric"><small>VENDOR CATEGORIES</small><strong>4</strong><small>Photography · DJs · Venues · Catering</small></div><div class="metric"><small>YOUR NEXT STEP</small><strong>Say hello.</strong><small>We’ll help with the paperwork.</small></div></div>`+intro()+`<section class="card"><h2>Take the onboarding journey</h2><p>Start with the manual process, then see how source imports simplify a rep’s day.</p><button class="secondary" onclick="start('before')">Explore before</button> <button class="primary" onclick="start('after')">Experience after →</button></section>`;else $('#app').innerHTML=heading('Good vendors. Great beginnings.','Bring your next wedding partner into the Bub’s family.',`<div class="switch"><button data-mode="before" class="${state.mode==='before'?'selected':''}">Before: manual</button><button data-mode="after" class="${state.mode==='after'?'selected':''}">✧ After: automated</button></div>`)+intro()+(state.mode==='before'?manualScreen():state.step===1?importScreen():state.step===2?reviewScreen():profile());bind()}
function start(mode){state.page='onboard';state.mode=mode;state.step=1;render();window.scrollTo(0,0)}
function showSource(k){$('#source-title').textContent=labels[k];$('#source-copy').textContent=k==='price'?`Website (sample): “Packages start at ${state.type==='Caterer'?'$75 per guest':state.type==='Venue'?'$7,500':state.type==='DJ'?'$2,000':'$3,800'}.”\n\nRecent call (sample): “Our current starting price is ${samples[state.type].price}.”\n\nThe newer call is suggested for review. The rep must confirm the final value.`:`${k==='bio'?'Drafted summary based on the fictional vendor website and call.':'Fictional vendor website / introductory call:'}\n\n${samples[state.type][k]}\n\nThis evidence demonstrates source attribution; it is not a live website extraction.`;$('#source').showModal()}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;render();window.scrollTo(0,0)});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;render()});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;state.url='';render()});document.querySelectorAll('[data-key]').forEach(x=>x.oninput=()=>{(state.mode==='before'?state.manual:state.data)[x.dataset.key]=x.value;if(state.mode==='before')$('.footer small').textContent=`${Object.values(state.manual).filter(Boolean).length} of 9 fields entered by hand`});if($('#type'))$('#type').onchange=e=>{state.type=e.target.value;state.url='';state.file='';state.transcript='';render()};if($('#url'))$('#url').oninput=e=>state.url=e.target.value;if($('#transcript'))$('#transcript').oninput=e=>state.transcript=e.target.value;if($('#sample'))$('#sample').onclick=()=>{state.url=`https://${samples[state.type].name.toLowerCase().replace(/[^a-z]/g,'')}.example`;render();toast('Sample vendor source added. Ready to generate.');};if($('#browse'))$('#browse').onclick=()=>$('#upload').click();async function loadFile(f){if(!f)return;if(!/\.(txt|vtt)$/i.test(f.name)||f.size>2097152){toast('Choose a TXT or VTT file under 2 MB.');return}state.file=f.name;state.transcript=await f.text();render()}if($('#upload')){$('#upload').onchange=e=>loadFile(e.target.files[0]);$('.drop').ondragover=e=>e.preventDefault();$('.drop').ondrop=e=>{e.preventDefault();loadFile(e.dataTransfer.files[0])}}if($('#extract'))$('#extract').onclick=()=>{if(state.tab==='transcript'?!state.transcript.trim():!/^https?:\/\/\S+\.\S+/.test(state.url)){toast(state.tab==='transcript'?'Paste a transcript or upload a file to continue.':'Add a valid URL, or use the sample vendor.');return}state.data={...samples[state.type]};state.resolved=false;$('#app').innerHTML=heading('A little magic. A lot less typing.','Preparing your sample vendor profile…')+`<section class="card loading"><span class="tag">✧ SIMULATED EXTRACTION</span><h2>Connecting the dots for ${esc(state.data.name)}</h2><p>Reading sources → organizing details → checking for conflicts</p><div class="progress"><span></span></div><small>Demo animation · No external sources are being fetched</small></section>`;setTimeout(()=>{state.step=2;render();window.scrollTo(0,0)},2100)};if($('#resolve'))$('#resolve').onclick=()=>{state.resolved=true;state.data.price=samples[state.type].price;render();toast('Pricing confirmed using the recent call.')};if($('#back'))$('#back').onclick=()=>{state.step=1;render()};if($('#approve'))$('#approve').onclick=()=>{if(Object.values(state.data).some(v=>!v.trim())){toast('Complete all vendor details before approval.');return}if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(state.data.email)){toast('Enter a valid contact email.');return}saved=saved.filter(v=>v.data.name!==state.data.name);saved.push({type:state.type,data:{...state.data}});try{localStorage.setItem('bubs-vendors',JSON.stringify(saved))}catch{toast('Browser storage unavailable; profile saved for this session.')}state.step=3;render();window.scrollTo(0,0)};if($('#another'))$('#another').onclick=()=>{state.url='';state.transcript='';state.file='';start('after')};if($('#switch-after'))$('#switch-after').onclick=()=>start('after');if($('#manual-save'))$('#manual-save').onclick=()=>toast('Manual worksheet saved for this session.');document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{const v=saved[Number(b.dataset.view)];state.data={...v.data};state.type=v.type;state.step=3;state.page='onboard';state.mode='after';render()});if($('#export'))$('#export').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({category:state.type,...state.data},null,2)],{type:'application/json'}));a.download='bubs-vendor-profile.json';a.click();URL.revokeObjectURL(a.href);toast('Vendor profile exported.')};}
render();





